    Outlook:{mark:'O',type:'Business email',method:'Graph notifications + delta',detail:'Authorised business mailbox. Permission and subscription health tracked separately.',requires:'Microsoft OAuth/tenant consent, least-privilege permissions, folder-scoped delta tracking, subscription renewal and missed-event reconciliation.'},
