    'Outlook Calendar':{mark:'□',type:'Calendar',method:'Graph event sync',detail:'Authorised Outlook calendar. No meeting invite is sent by this preview.',requires:'Microsoft calendar permissions, selected calendar, change/delta support verification, renewal and explicit approval for external invitations.'}
