  const chip=(value,kind='')=>'<span data-stage="'+(stages.includes(value)?value:'')+'" class="gh-pill '+kind+'">'+esc(value)+'</span>';
  const note=text=>'<div class="gh-note">'+text+'</div>';
  const empty=text=>'<div class="bi-chart-empty">'+text+'</div>';
  const title=(heading,sub='',right='')=>'<div class="gh-head"><div><h2>'+heading+'</h2>'+(sub?'<small>'+sub+'</small>':'')+'</div>'+right+'</div>';
  const announce=text=>{$('ghStatus').textContent=text;QSDash.toast(text);};
  const formField=(label,name,html,full=false)=>'<label class="gh-field '+(full?'full':'')+'"><span>'+label+'</span>'+html+'</label>';
  const input=(name,value='',type='text',max=120)=>'<input name="'+name+'" type="'+type+'" value="'+esc(value)+'" maxlength="'+max+'">';
  const select=(name,values,value)=>'<select name="'+name+'">'+(name==='owner'?'<option value="" '+(!value?'selected':'')+'>Unassigned</option>':'')+opt(values,value)+'</select>';
