  function stamp(d){return new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(d))+' IST';}
  function controls(){const reporting=['overview','leads','performance'].includes(state.tab);
    $('biControls').innerHTML='<div class="bi-datebar"><div class="bi-date-controls" '+(reporting?'':'hidden')+'><label>Period <select id="biPeriod">'+[['today','Today'],['7d','Last 7 days'],['30d','Last 30 days'],['month','This month'],['lastmonth','Last month'],['6m','Last 6 months'],['all','Available history'],['custom','Custom range']].map(([v,t])=>'<option value="'+v+'" '+(v===state.period?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label>Group <select id="biGrain">'+[['month','Monthly'],['day','Daily'],['year','Yearly']].map(([v,t])=>'<option value="'+v+'" '+(v===state.grain?'selected':'')+'>'+t+'</option>').join('')+'</select></label><div id="biCustomDates" '+(state.period==='custom'?'':'hidden')+'><label>From <input type="date" id="biStart" value="'+state.range.start+'" min="'+state.historyStart+'" max="'+today+'"></label><label>To <input type="date" id="biEnd" value="'+state.range.end+'" min="'+state.historyStart+'" max="'+today+'"></label>'+btn('apply-range','Apply')+'</div></div>'+(reporting?'':'<span class="pulse-context-caption">'+PulseBrand.symbol('layers')+'<strong>Operations workspace</strong><span>Current queues · all recorded dates</span></span>')+'<span class="bi-mode">'+(live()?'LIVE STUDIO DATA · NO PROVIDER SYNC CONNECTED':'UNCONNECTED WORKSPACE')+' <button type="button" data-bi-action="mode">'+(live()?'View unconnected':'View live Studio data')+'</button></span></div><p class="bi-range-caption">'+(reporting?formatDay(state.range.start)+' – '+formatDay(state.range.end)+' '+state.range.end.slice(0,4)+' · Asia/Kolkata · '+(live()?'Live Studio records; provider backfill is not connected yet.':'No Studio backend or provider data is connected in this isolated view.'):'Current operations · Asia/Kolkata · '+(live()?'Live Studio queues. Not limited by report dates.':'No connected Studio records.'))+'</p><p id="biDateError" class="bi-date-error" role="status" hidden></p>';
  }
